<?php
namespace Kitmage\Tutor\Entitlements\Service;
use Kitmage\Tutor\Entitlements\Repository\BatchRepository;
final class ProvisioningService {
	public function provision_order($order_id){$order=wc_get_order($order_id);if(!$order||!$order->is_paid())return;foreach($order->get_items('line_item') as $item_id=>$item){$product=$item->get_product();if(!$product)continue;$variation=$product->is_type('variation')?$product:null;$parent=$variation?wc_get_product($variation->get_parent_id()):$product;$enabled=$this->meta($variation,$parent,'_kte_enabled');if('yes'!==$enabled)continue;$course=(int)$this->meta($variation,$parent,'_kte_course_id');$per=(int)$this->meta($variation,$parent,'_kte_seats_per_unit');$days=(int)$this->meta($variation,$parent,'_kte_redemption_days');if(!$course||$per<1||$days<1||!tutor_utils()->is_course_entitlement_only($course))continue;$sub=0;if(function_exists('wcs_get_subscriptions_for_order')){$subs=wcs_get_subscriptions_for_order($order_id,array('order_type'=>'any'));if($subs)$sub=(int)array_key_first($subs);}$created=(new BatchRepository())->create(array('customer_user_id'=>$order->get_customer_id(),'order_id'=>$order->get_id(),'order_item_id'=>$item_id,'subscription_id'=>$sub,'product_id'=>$parent->get_id(),'variation_id'=>$variation?$variation->get_id():0,'course_id'=>$course,'entitlements_total'=>$per*(int)$item->get_quantity(),'expires_at'=>gmdate('Y-m-d H:i:s',current_time('timestamp',true)+$days*DAY_IN_SECONDS),'created_by'=>$sub?'subscription_payment':'order_payment'));if($created)do_action('kitmage_training_entitlements/batch_created',$created['id'],$order->get_id(),(int)$item_id);}}
	private function meta($variation,$parent,$key){if($variation){$v=$variation->get_meta($key,true);if(''!==$v)return $v;}return $parent->get_meta($key,true);}
}
